#!/usr/bin/env python3
# FELFEL_PHASE3_CLIENT_MEETING_INTELLIGENCE_PATCH_V2
from pathlib import Path

ROOT = Path("/var/www/TCRM-MAIN")
if not ROOT.exists():
    raise SystemExit("TCRM root not found")

def read(rel):
    return (ROOT / rel).read_text(encoding="utf-8")

def write(rel, text):
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly 1 anchor, found {count}")
    return text.replace(old, new, 1)

COMPONENT = "// FELFEL_PHASE3_CLIENT_MEETING_INTELLIGENCE_V1\n// @ts-nocheck\nimport { useMemo, useState } from \"react\";\nimport { BrainCircuit, CheckSquare2, CircleAlert, Lightbulb, ListChecks, Loader2, MessageCircleQuestion, ShieldAlert, Sparkles } from \"lucide-react\";\nimport { trpc } from \"@/lib/trpc\";\nimport { Button } from \"@/components/ui/button\";\nimport { Input } from \"@/components/ui/input\";\nimport { Badge } from \"@/components/ui/badge\";\nimport { toast } from \"sonner\";\n\nfunction rows(value: unknown): any[] {\n  return Array.isArray(value) ? value : [];\n}\n\nfunction textOf(value: any) {\n  return String(value?.task || value?.decision || value?.question || value?.text || value || \"\").trim();\n}\n\nfunction formatDate(value: unknown, ar: boolean) {\n  if (!value) return \"—\";\n  const date = new Date(String(value));\n  if (Number.isNaN(date.getTime())) return String(value);\n  return date.toLocaleString(ar ? \"ar-EG\" : \"en-US\", { dateStyle: \"medium\", timeStyle: \"short\" });\n}\n\nexport default function FelfelMeetingIntelligencePanel({\n  meeting,\n  isRTL,\n}: {\n  meeting: any;\n  isRTL: boolean;\n}) {\n  const ar = isRTL;\n  const utils = trpc.useUtils();\n  const analysis = meeting?.analysisData || {};\n  const opinion = analysis?.felfelOpinion || {};\n  const memory = meeting?.memoryData || {};\n  const decisions = rows(analysis?.decisions);\n  const actions = rows(analysis?.actionItems);\n  const risks = rows(opinion?.risks);\n  const opportunities = rows(opinion?.opportunities);\n  const recommendations = rows(opinion?.recommendations);\n  const questions = rows(opinion?.followUpQuestions);\n  const relatedTaskIds = rows(meeting?.relatedTaskIds);\n  const relatedFollowUpIds = rows(meeting?.relatedFollowUpIds);\n  const [selectedActions, setSelectedActions] = useState<Record<number, boolean>>({});\n  const [followUpType, setFollowUpType] = useState<\"Call\" | \"Meeting\" | \"WhatsApp\" | \"Email\">(\"Call\");\n  const [followUpAt, setFollowUpAt] = useState(\"\");\n  const [followUpTopic, setFollowUpTopic] = useState(\"\");\n\n  const selected = useMemo(\n    () => actions.map((item, index) => ({ item, index })).filter(({ index }) => selectedActions[index]),\n    [actions, selectedActions],\n  );\n\n  const nativeId = String(meeting?.nativeMeetingId || \"\").trim();\n  const platform = String(meeting?.platform || \"\").trim();\n  const clientId = Number(meeting?.clientId || 0);\n  const dealId = Number(meeting?.dealId || 0) || null;\n  const canWriteCrm = Boolean(clientId > 0 && nativeId && platform);\n\n  const refresh = async () => {\n    await Promise.allSettled([\n      utils.felfel.dashboardMeetings.invalidate(),\n      utils.felfel.listLinkedMeetings.invalidate(),\n    ]);\n  };\n\n  const createTasks = trpc.felfel.createApprovedTasks.useMutation({\n    onSuccess: async (data: any) => {\n      toast.success(\n        ar\n          ? `تم اعتماد ${Number(data?.createdCount || 0)} مهمة${Number(data?.duplicateCount || 0) ? ` وتخطي ${Number(data.duplicateCount)} مكررة` : \"\"}`\n          : `Approved ${Number(data?.createdCount || 0)} task(s)${Number(data?.duplicateCount || 0) ? `; skipped ${Number(data.duplicateCount)} duplicate(s)` : \"\"}`,\n      );\n      setSelectedActions({});\n      await refresh();\n    },\n    onError: (error) => toast.error(error.message),\n  });\n\n  const createFollowUp = trpc.felfel.createFollowUp.useMutation({\n    onSuccess: async (data: any) => {\n      toast.success(\n        data?.duplicate\n          ? (ar ? \"المتابعة معتمدة بالفعل\" : \"Follow-up already exists\")\n          : (ar ? \"تم اعتماد المتابعة داخل CRM\" : \"Follow-up approved in CRM\"),\n      );\n      setFollowUpAt(\"\");\n      setFollowUpTopic(\"\");\n      await refresh();\n    },\n    onError: (error) => toast.error(error.message),\n  });\n\n  const approveTasks = () => {\n    if (!canWriteCrm || !selected.length) return;\n    createTasks.mutate({\n      clientId,\n      dealId,\n      platform: platform as any,\n      nativeId,\n      generatedAt: analysis?.generatedAt || null,\n      confirm: true,\n      tasks: selected.map(({ item, index }) => ({\n        sourceIndex: index,\n        title: textOf(item),\n        priority: item?.priority || \"unknown\",\n        aiOwner: item?.owner || null,\n        aiDueDate: item?.dueDate || null,\n      })),\n    });\n  };\n\n  const approveFollowUp = () => {\n    if (!canWriteCrm || !followUpAt) return;\n    const parsed = new Date(followUpAt);\n    if (Number.isNaN(parsed.getTime())) {\n      toast.error(ar ? \"اختر تاريخ ووقت صحيح للمتابعة\" : \"Choose a valid follow-up date and time\");\n      return;\n    }\n    createFollowUp.mutate({\n      clientId,\n      dealId,\n      platform: platform as any,\n      nativeId,\n      type: followUpType,\n      followUpAt: parsed.toISOString(),\n      topic: followUpTopic.trim() || null,\n      confirm: true,\n    });\n  };\n\n  const hasIntelligence = Boolean(\n    analysis?.summary ||\n    opinion?.headline ||\n    decisions.length ||\n    actions.length ||\n    risks.length ||\n    opportunities.length ||\n    recommendations.length ||\n    questions.length ||\n    Number(memory?.previousMeetingCount || 0) > 0\n  );\n\n  if (!hasIntelligence) {\n    return (\n      <div className=\"mt-4 rounded-2xl border border-dashed border-border/70 p-4 text-center text-xs text-muted-foreground\">\n        {ar ? \"ذكاء الاجتماع سيظهر هنا بعد اكتمال التحليل.\" : \"Meeting intelligence will appear here after analysis completes.\"}\n      </div>\n    );\n  }\n\n  return (\n    <section className=\"mt-4 space-y-3 rounded-2xl border border-orange-500/15 bg-orange-500/[0.025] p-4\" data-felfel-intelligence=\"phase3-v1\">\n      <div className=\"flex flex-wrap items-center justify-between gap-2\">\n        <div className=\"flex items-center gap-2\">\n          <BrainCircuit className=\"h-4 w-4 text-orange-500\" />\n          <span className=\"text-sm font-black\">{ar ? \"ذكاء الاجتماع — فلفل\" : \"Felfel Meeting Intelligence\"}</span>\n          {analysis?.generatedAt && <Badge variant=\"outline\">{formatDate(analysis.generatedAt, ar)}</Badge>}\n        </div>\n        {(relatedTaskIds.length > 0 || relatedFollowUpIds.length > 0) && (\n          <div className=\"text-[11px] text-muted-foreground\">\n            {relatedTaskIds.length ? `${ar ? \"مهام\" : \"Tasks\"}: ${relatedTaskIds.join(\", \")}` : \"\"}\n            {relatedTaskIds.length && relatedFollowUpIds.length ? \" · \" : \"\"}\n            {relatedFollowUpIds.length ? `${ar ? \"متابعات\" : \"Follow-ups\"}: ${relatedFollowUpIds.join(\", \")}` : \"\"}\n          </div>\n        )}\n      </div>\n\n      {(opinion?.headline || analysis?.summary) && (\n        <div className=\"grid gap-3 lg:grid-cols-2\">\n          {opinion?.headline && (\n            <div className=\"rounded-xl bg-background p-3\">\n              <div className=\"mb-1 flex items-center gap-1.5 text-xs font-bold text-orange-600\"><Sparkles className=\"h-3.5 w-3.5\" />{ar ? \"الخلاصة التنفيذية\" : \"Executive take\"}</div>\n              <p className=\"text-sm leading-6\">{opinion.headline}</p>\n            </div>\n          )}\n          {analysis?.summary && (\n            <div className=\"rounded-xl bg-background p-3\">\n              <div className=\"mb-1 text-xs font-bold text-muted-foreground\">{ar ? \"ملخص الاجتماع\" : \"Meeting summary\"}</div>\n              <p className=\"whitespace-pre-wrap text-sm leading-6\">{analysis.summary}</p>\n            </div>\n          )}\n        </div>\n      )}\n\n      <div className=\"grid gap-3 lg:grid-cols-2\">\n        {decisions.length > 0 && (\n          <div className=\"rounded-xl bg-background p-3\">\n            <div className=\"mb-2 flex items-center gap-1.5 text-xs font-bold\"><ListChecks className=\"h-3.5 w-3.5 text-blue-600\" />{ar ? \"القرارات\" : \"Decisions\"}</div>\n            <ul className=\"space-y-2 text-sm\">\n              {decisions.map((item, index) => <li key={index} className=\"rounded-lg bg-muted/35 p-2\">{textOf(item)}{(item?.owner || item?.dueDate) && <div className=\"mt-1 text-[11px] text-muted-foreground\">{item?.owner ? `${ar ? \"المسؤول\" : \"Owner\"}: ${item.owner}` : \"\"}{item?.owner && item?.dueDate ? \" · \" : \"\"}{item?.dueDate ? `${ar ? \"الموعد\" : \"Due\"}: ${item.dueDate}` : \"\"}</div>}</li>)}\n            </ul>\n          </div>\n        )}\n\n        {(risks.length || opportunities.length || recommendations.length) > 0 && (\n          <div className=\"rounded-xl bg-background p-3\">\n            <div className=\"grid gap-3\">\n              {risks.length > 0 && <div><div className=\"mb-1 flex items-center gap-1.5 text-xs font-bold text-red-600\"><ShieldAlert className=\"h-3.5 w-3.5\" />{ar ? \"المخاطر\" : \"Risks\"}</div><ul className=\"list-disc space-y-1 ps-5 text-sm\">{risks.map((item, i) => <li key={i}>{textOf(item)}</li>)}</ul></div>}\n              {opportunities.length > 0 && <div><div className=\"mb-1 flex items-center gap-1.5 text-xs font-bold text-emerald-600\"><Lightbulb className=\"h-3.5 w-3.5\" />{ar ? \"الفرص\" : \"Opportunities\"}</div><ul className=\"list-disc space-y-1 ps-5 text-sm\">{opportunities.map((item, i) => <li key={i}>{textOf(item)}</li>)}</ul></div>}\n              {recommendations.length > 0 && <div><div className=\"mb-1 text-xs font-bold text-violet-600\">{ar ? \"توصيات فلفل\" : \"Felfel recommendations\"}</div><ul className=\"list-disc space-y-1 ps-5 text-sm\">{recommendations.map((item, i) => <li key={i}>{textOf(item)}</li>)}</ul></div>}\n            </div>\n          </div>\n        )}\n      </div>\n\n      {questions.length > 0 && (\n        <div className=\"rounded-xl bg-background p-3\">\n          <div className=\"mb-2 flex items-center gap-1.5 text-xs font-bold\"><MessageCircleQuestion className=\"h-3.5 w-3.5 text-cyan-600\" />{ar ? \"أسئلة المتابعة المقترحة\" : \"Suggested follow-up questions\"}</div>\n          <ul className=\"grid gap-2 text-sm md:grid-cols-2\">{questions.map((item, i) => <li key={i} className=\"rounded-lg bg-muted/35 p-2\">{textOf(item)}</li>)}</ul>\n        </div>\n      )}\n\n      {Number(memory?.previousMeetingCount || 0) > 0 && (\n        <div className=\"rounded-xl border border-blue-500/15 bg-blue-500/[0.035] p-3\">\n          <div className=\"mb-2 text-xs font-black text-blue-700 dark:text-blue-300\">{ar ? \"ذاكرة العلاقة\" : \"Relationship memory\"} · {Number(memory.previousMeetingCount)} {ar ? \"اجتماعات سابقة\" : \"prior meetings\"}</div>\n          <div className=\"grid gap-3 md:grid-cols-2\">\n            {rows(memory?.repeatedObjections).length > 0 && <div><div className=\"text-[11px] font-bold text-muted-foreground\">{ar ? \"مخاطر/اعتراضات متكررة\" : \"Repeated risks / objections\"}</div><ul className=\"mt-1 list-disc space-y-1 ps-5 text-sm\">{rows(memory.repeatedObjections).map((item, i) => <li key={i}>{textOf(item)}</li>)}</ul></div>}\n            {rows(memory?.unresolvedCommitments).length > 0 && <div><div className=\"text-[11px] font-bold text-muted-foreground\">{ar ? \"التزامات سابقة غير محسومة\" : \"Unresolved prior commitments\"}</div><ul className=\"mt-1 list-disc space-y-1 ps-5 text-sm\">{rows(memory.unresolvedCommitments).map((item, i) => <li key={i}>{textOf(item)}</li>)}</ul></div>}\n          </div>\n        </div>\n      )}\n\n      {actions.length > 0 && (\n        <div className=\"rounded-xl border border-emerald-500/15 bg-emerald-500/[0.025] p-3\">\n          <div className=\"mb-2 flex items-center justify-between gap-2\">\n            <div className=\"flex items-center gap-1.5 text-xs font-black\"><CheckSquare2 className=\"h-3.5 w-3.5 text-emerald-600\" />{ar ? \"عناصر العمل المقترحة\" : \"Suggested action items\"}</div>\n            <span className=\"text-[11px] text-muted-foreground\">{ar ? \"لا يتم إنشاء أي مهمة بدون اعتمادك\" : \"Nothing is created without your approval\"}</span>\n          </div>\n          <div className=\"space-y-2\">\n            {actions.map((item, index) => (\n              <label key={index} className={`flex cursor-pointer items-start gap-2 rounded-lg border p-2.5 ${selectedActions[index] ? \"border-emerald-500/40 bg-emerald-500/5\" : \"border-border/60 bg-background\"}`}>\n                <input type=\"checkbox\" className=\"mt-1\" checked={Boolean(selectedActions[index])} onChange={(event) => setSelectedActions((current) => ({ ...current, [index]: event.target.checked }))} disabled={!canWriteCrm || createTasks.isPending} />\n                <span className=\"min-w-0 flex-1 text-sm\">{textOf(item)}{(item?.owner || item?.dueDate || item?.priority) && <span className=\"mt-1 block text-[11px] text-muted-foreground\">{item?.priority ? `${ar ? \"الأولوية\" : \"Priority\"}: ${item.priority}` : \"\"}{item?.owner ? ` · ${ar ? \"مقترح للمسؤول\" : \"Suggested owner\"}: ${item.owner}` : \"\"}{item?.dueDate ? ` · ${ar ? \"موعد مذكور\" : \"Mentioned due\"}: ${item.dueDate}` : \"\"}</span>}</span>\n              </label>\n            ))}\n          </div>\n          <div className=\"mt-3 flex flex-wrap items-center gap-2\">\n            <Button size=\"sm\" onClick={approveTasks} disabled={!canWriteCrm || !selected.length || createTasks.isPending}>\n              {createTasks.isPending && <Loader2 className=\"me-1 h-3.5 w-3.5 animate-spin\" />}\n              {ar ? `اعتماد وإنشاء ${selected.length || \"\"} مهمة` : `Approve & create ${selected.length || \"\"} task(s)`}\n            </Button>\n            {!canWriteCrm && <span className=\"text-[11px] text-muted-foreground\">{ar ? \"يلزم ربط الاجتماع بعميل CRM لإنشاء المهام.\" : \"Link this meeting to a CRM client before creating tasks.\"}</span>}\n          </div>\n        </div>\n      )}\n\n      <div className=\"rounded-xl border border-cyan-500/15 bg-cyan-500/[0.025] p-3\">\n        <div className=\"mb-2 flex items-center gap-1.5 text-xs font-black\"><MessageCircleQuestion className=\"h-3.5 w-3.5 text-cyan-600\" />{ar ? \"اعتماد متابعة CRM\" : \"Approve CRM follow-up\"}</div>\n        <div className=\"grid gap-2 md:grid-cols-[140px_220px_1fr_auto]\">\n          <select value={followUpType} onChange={(event) => setFollowUpType(event.target.value as any)} className=\"h-9 rounded-md border border-input bg-background px-2 text-sm\" disabled={!canWriteCrm || createFollowUp.isPending}>\n            <option value=\"Call\">{ar ? \"مكالمة\" : \"Call\"}</option><option value=\"Meeting\">{ar ? \"اجتماع\" : \"Meeting\"}</option><option value=\"WhatsApp\">WhatsApp</option><option value=\"Email\">Email</option>\n          </select>\n          <Input type=\"datetime-local\" value={followUpAt} onChange={(event) => setFollowUpAt(event.target.value)} disabled={!canWriteCrm || createFollowUp.isPending} />\n          <Input value={followUpTopic} onChange={(event) => setFollowUpTopic(event.target.value)} maxLength={2000} placeholder={ar ? \"موضوع المتابعة — راجعه قبل الاعتماد\" : \"Follow-up topic — review before approval\"} disabled={!canWriteCrm || createFollowUp.isPending} />\n          <Button size=\"sm\" className=\"h-9\" onClick={approveFollowUp} disabled={!canWriteCrm || !followUpAt || createFollowUp.isPending}>\n            {createFollowUp.isPending && <Loader2 className=\"me-1 h-3.5 w-3.5 animate-spin\" />}{ar ? \"اعتماد\" : \"Approve\"}\n          </Button>\n        </div>\n        <div className=\"mt-2 flex items-start gap-1.5 text-[11px] text-muted-foreground\"><CircleAlert className=\"mt-0.5 h-3.5 w-3.5 shrink-0\" />{ar ? \"التاريخ والوقت يتم اختيارهما يدويًا؛ فلفل لا يحوّل موعدًا لغويًا إلى متابعة تلقائيًا.\" : \"Date and time are selected by a human; Felfel does not auto-schedule natural-language dates.\"}</div>\n      </div>\n    </section>\n  );\n}\n"
component_path = "client/src/components/felfel/FelfelMeetingIntelligencePanel.tsx"
existing_component = read(component_path) if (ROOT / component_path).exists() else ""
if "FELFEL_PHASE3_CLIENT_MEETING_INTELLIGENCE_V1" not in existing_component:
    write(component_path, COMPONENT)

rel = "server/services/felfel/felfelDashboardService.ts"
text = read(rel)
if "analysisData: crmMeetings.analysisData" not in text:
    text = replace_once(text, "    analysisStatus: crmMeetings.analysisStatus,\n    scheduledAt: crmMeetings.scheduledAt,", "    analysisStatus: crmMeetings.analysisStatus,\n    analysisData: crmMeetings.analysisData,\n    memoryData: crmMeetings.memoryData,\n    relatedTaskIds: crmMeetings.relatedTaskIds,\n    relatedFollowUpIds: crmMeetings.relatedFollowUpIds,\n    scheduledAt: crmMeetings.scheduledAt,", "dashboard intelligence select")
    write(rel, text)

rel = "client/src/components/felfel/FelfelOperationalDashboard.tsx"
text = read(rel)
if "FelfelMeetingIntelligencePanel" not in text:
    text = replace_once(text, "import FelfelMeetingTitleEditor from \"@/components/felfel/FelfelMeetingTitleEditor\";", "import FelfelMeetingTitleEditor from \"@/components/felfel/FelfelMeetingTitleEditor\";\nimport FelfelMeetingIntelligencePanel from \"@/components/felfel/FelfelMeetingIntelligencePanel\";", "operational intelligence import")
    text = replace_once(text, "                    <div className=\"mt-4 grid gap-3 xl:grid-cols-2\">\n                      <FelfelRecordingPlayer media={meeting.recordingMedia} driveUrl={meeting.recordingDriveUrl} durationSec={meeting.recordingDurationSec} sizeBytes={meeting.recordingSizeBytes} isRTL={isRTL} />\n                      <FelfelTranscriptPanel segments={meeting.transcriptSegments} status={meeting.transcriptStatus} isRTL={isRTL} />\n                    </div>", "                    <div className=\"mt-4 grid gap-3 xl:grid-cols-2\">\n                      <FelfelRecordingPlayer media={meeting.recordingMedia} driveUrl={meeting.recordingDriveUrl} durationSec={meeting.recordingDurationSec} sizeBytes={meeting.recordingSizeBytes} isRTL={isRTL} />\n                      <FelfelTranscriptPanel segments={meeting.transcriptSegments} status={meeting.transcriptStatus} isRTL={isRTL} />\n                    </div>\n                    <FelfelMeetingIntelligencePanel meeting={meeting} isRTL={isRTL} />", "operational intelligence render")
    write(rel, text)

rel = "client/src/components/FelfelMeetingsHub.tsx"
text = read(rel)
if "import FelfelMeetingIntelligencePanel" not in text:
    text = replace_once(text, "import FelfelMeetingTitleEditor from \"@/components/felfel/FelfelMeetingTitleEditor\";", "import FelfelMeetingTitleEditor from \"@/components/felfel/FelfelMeetingTitleEditor\";\nimport FelfelMeetingIntelligencePanel from \"@/components/felfel/FelfelMeetingIntelligencePanel\";", "client history intelligence import")

if '<FelfelMeetingIntelligencePanel meeting={meeting} isRTL={isRTL} />' not in text:
    start_token = "            {(analysis.summary || decisions.length || actions.length || opinion.risks?.length || opinion.opportunities?.length || opinion.recommendations?.length || questions.length || taskIds.length || followUpIds.length || memory.previousMeetingCount) > 0 && <div className=\"mt-4 grid gap-3 md:grid-cols-2\">"
    end_token = "            <div className=\"mt-4 flex flex-wrap gap-2 text-xs text-muted-foreground\">"
    start = text.find(start_token)
    end = text.find(end_token, start if start >= 0 else 0)
    if start < 0 or end < 0 or end <= start:
        raise RuntimeError("client history intelligence block anchors not found")
    text = text[:start] + '            <FelfelMeetingIntelligencePanel meeting={meeting} isRTL={isRTL} />\n' + text[end:]
    write(rel, text)

